import pytest

from inventory import reserve


def test_late_shortage_keeps_entire_stock():
    stock = {"tea": 5, "coffee": 1}
    with pytest.raises(ValueError):
        reserve(stock, [("tea", 2), ("coffee", 2)])
    assert stock == {"tea": 5, "coffee": 1}


def test_repeated_product_shortage_keeps_stock():
    stock = {"tea": 5}
    with pytest.raises(ValueError):
        reserve(stock, [("tea", 3), ("tea", 3)])
    assert stock == {"tea": 5}


def test_late_invalid_quantity_keeps_stock():
    stock = {"tea": 5, "coffee": 1}
    with pytest.raises(ValueError):
        reserve(stock, [("tea", 2), ("coffee", 0)])
    assert stock == {"tea": 5, "coffee": 1}

